                relative h-16 rounded-lg overflow-hidden cursor-pointer
                transition-all duration-200
                ${isSelectedBg(bg) ? 'ring-4 ring-primary ring-offset-2 ring-offset-background' : 'hover:ring-2 hover:ring-default-300'}
