import { useEffect, useState } from "react";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, Input, Popover, PopoverTrigger, PopoverContent } from "@nextui-org/react";
import { Palette, Check } from "lucide-react";
import { LIST_COLORS } from "../../../utils/boardBackgrounds";

const EditListModal = ({ isOpen, onClose, initialName, initialColor, onSave }) => {
    const [nombre, setNombre] = useState(initialName);
    const [color, setColor] = useState(initialColor);

    // Resetear estado al abrir
    useEffect(() => {
        if (isOpen) {
            setNombre(initialName);
            setColor(initialColor);
        }
    }, [isOpen, initialName, initialColor]);

    const handleSave = () => {
        if (nombre.trim()) {
            onSave(nombre.trim(), color);
            onClose();
        }
    };

    const handleKeyDown = (e) => {
        if (e.key === 'Enter') handleSave();
    };

    return (
        <Modal isOpen={isOpen} onOpenChange={onClose} size="sm" placement="center" backdrop="blur">
            <ModalContent>
                {(onClose) => (
                    <>
                        <ModalHeader className="flex flex-col gap-1">Editar Lista</ModalHeader>
                        <ModalBody>
                            <div className="flex flex-col gap-4">
                                <Input
                                    autoFocus
                                    label="Nombre de la lista"
                                    placeholder="Ej: Tareas pendientes"
                                    value={nombre}
                                    onChange={(e) => setNombre(e.target.value)}
                                    onKeyDown={handleKeyDown}
                                    variant="bordered"
                                />

                                <div>
                                    <p className="text-small text-default-500 mb-2">Color de la lista</p>
                                    <div className="flex flex-wrap gap-2">
                                        {LIST_COLORS.map((c) => (
                                            <button
                                                key={c.id}
                                                onClick={() => setColor(c.value)}
                                                className={`
                                                    w-8 h-8 rounded-full transition-all flex items-center justify-center
                                                    ${c.id === 'none' ? 'border-2 border-default-300 bg-default-100' : ''}
                                                    ${color === c.value ? 'ring-2 ring-primary ring-offset-2 scale-110' : 'hover:scale-105'}
                                                `}
                                                style={c.value ? { backgroundColor: c.value } : {}}
                                                title={c.name}
                                            >
                                                {c.id === 'none' && !color && <Check size={14} />}
                                                {color === c.value && c.id !== 'none' && <Check size={14} className="text-white drop-shadow-md" />}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </ModalBody>
                        <ModalFooter>
                            <Button variant="light" onPress={onClose}>
                                Cancelar
                            </Button>
                            <Button color="primary" onPress={handleSave}>
                                Guardar
                            </Button>
                        </ModalFooter>
                    </>
                )}
            </ModalContent>
        </Modal>
    );
};

export default EditListModal;

import { useState } from "react";
import { Draggable } from "@hello-pangea/dnd";
import { Card, CardBody, Chip, Checkbox, useDisclosure, Dropdown, DropdownTrigger, DropdownMenu, DropdownItem, Button } from "@nextui-org/react";
import { Calendar, Tag, GripVertical, MoreVertical, Edit2, Trash2, Clock } from "lucide-react";
import TaskCardModal from "./TaskCardModal";
import { format, isPast, isToday, isTomorrow } from "date-fns";
import { es } from "date-fns/locale";
import { toast } from "sonner";

const TaskCard = ({ tarjeta, index, toggleCompletada, editarTarjeta, borrarTarjeta }) => {
    const { isOpen, onOpen, onOpenChange } = useDisclosure();

    const handleToggle = async (isSelected) => {
        await toggleCompletada(tarjeta.id, tarjeta.completada);
    };

    const handleDelete = async () => {
        try {
            toast.success("Tarea eliminada");
            await borrarTarjeta(tarjeta.id);
        } catch (error) {
            console.error(error);
            toast.error("Hubo un error al eliminar");
        }
    };

    const getFechaInfo = () => {
        if (!tarjeta.fechaVencimiento) return null;

        const fecha = new Date(tarjeta.fechaVencimiento);

        if (tarjeta.completada) {
            return { color: "success", text: "Completada", icon: "✓" };
        }

        if (isPast(fecha) && !isToday(fecha)) {
            return { color: "danger", text: "Vencida", icon: "!" };
        }

        if (isToday(fecha)) {
            return { color: "warning", text: "Hoy", icon: "⚡" };
        }

        if (isTomorrow(fecha)) {
            return { color: "warning", text: "Mañana", icon: "📅" };
        }

        return {
            color: "default",
            text: format(fecha, "d MMM", { locale: es }),
            icon: "📆"
        };
    };

    const fechaInfo = getFechaInfo();

    return (
        <>
            <Draggable draggableId={tarjeta.id} index={index}>
                {(provided, snapshot) => (
                    <div
                        ref={provided.innerRef}
                        {...provided.draggableProps}
                        className="mb-2"
                    >
                        <Card
                            className={`
                group
                bg-white dark:bg-default-100 
                border-2 border-default-200
                hover:border-primary hover:shadow-lg 
                transition-all duration-200
                ${snapshot.isDragging ? 'shadow-2xl rotate-2 scale-105 border-primary' : ''}
                ${tarjeta.completada ? 'opacity-70' : ''}
              `}
                        >
                            <CardBody className="p-3 cursor-pointer" onClick={onOpen}>
                                <div className="flex items-start gap-2">
                                    {/* Drag Handle */}
                                    <div
                                        {...provided.dragHandleProps}
                                        className="cursor-grab active:cursor-grabbing text-default-300 hover:text-primary mt-0.5 opacity-0 group-hover:opacity-100 transition-opacity"
                                        onClick={(e) => e.stopPropagation()}
                                    >
                                        <GripVertical size={16} />
                                    </div>

                                    {/* Checkbox */}
                                    <div onClick={(e) => e.stopPropagation()}>
                                        <Checkbox
                                            isSelected={tarjeta.completada}
                                            onValueChange={handleToggle}
                                            size="sm"
                                            color="success"
                                            className="mt-0.5"
                                        />
                                    </div>

                                    {/* Contenido */}
                                    <div className="flex-1 min-w-0">
                                        <h4 className={`font-semibold text-sm mb-1 ${tarjeta.completada ? 'line-through text-default-400' : 'text-foreground'}`}>
                                            {tarjeta.titulo}
                                        </h4>

                                        {tarjeta.descripcion && (
                                            <p className="text-xs text-default-500 line-clamp-2 mb-2">
                                                {tarjeta.descripcion}
                                            </p>
                                        )}

                                        {/* Metadatos */}
                                        <div className="flex flex-wrap gap-1.5 items-center">
                                            {tarjeta.fechaVencimiento && (
                                                <Chip
                                                    size="sm"
                                                    variant="flat"
                                                    color={
                                                        new Date(tarjeta.fechaVencimiento) < new Date()
                                                            ? "danger"
                                                            : "default"
                                                    }
                                                    startContent={<Calendar size={12} />}
                                                    className="text-xs"
                                                >
                                                    {format(new Date(tarjeta.fechaVencimiento), "d MMM", { locale: es })}
                                                </Chip>
                                            )}

                                            {tarjeta.etiquetas?.map((etiqueta) => (
                                                <Chip
                                                    key={etiqueta.id}
                                                    size="sm"
                                                    color={etiqueta.color}
                                                    variant="flat"
                                                    className="text-xs"
                                                >
                                                    {etiqueta.nombre}
                                                </Chip>
                                            ))}
                                        </div>
                                    </div>

                                    {/* Dropdown Menu */}
                                    <div onClick={(e) => e.stopPropagation()}>
                                        <Dropdown>
                                            <DropdownTrigger>
                                                <Button
                                                    isIconOnly
                                                    size="sm"
                                                    variant="light"
                                                    className="z-10 aria-expanded:opacity-100 opacity-0 group-hover:opacity-100 transition-opacity"
                                                >
                                                    <MoreVertical size={16} />
                                                </Button>
                                            </DropdownTrigger>
                                            <DropdownMenu aria-label="Acciones de tarjeta">
                                                <DropdownItem
                                                    key="edit"
                                                    startContent={<Edit2 size={14} />}
                                                    onPress={onOpen}
                                                >
                                                    Editar
                                                </DropdownItem>
                                                <DropdownItem
                                                    key="delete"
                                                    className="text-danger"
                                                    color="danger"
                                                    startContent={<Trash2 size={14} />}
                                                    onPress={handleDelete}
                                                >
                                                    Eliminar
                                                </DropdownItem>
                                            </DropdownMenu>
                                        </Dropdown>
                                    </div>
                                </div>
                            </CardBody>
                        </Card>
                    </div>
                )}
            </Draggable>

            <TaskCardModal
                isOpen={isOpen}
                onOpenChange={onOpenChange}
                tarjeta={tarjeta}
                mode="edit"
            />
        </>
    );
};

export default TaskCard;

import { useState, useEffect } from "react";
import {
    Modal, ModalContent, ModalHeader, ModalBody, ModalFooter,
    Button, Input, Textarea, Chip, Divider
} from "@nextui-org/react";
import { Calendar, Tag, Trash2, Save, CalendarPlus } from "lucide-react";
import { useTarjetas } from "../../../hooks/useTarjetas";
import { useTodos } from "../../../hooks/useTodos";
import { toast } from "sonner";
import { format } from "date-fns";
import { es } from "date-fns/locale";

const ETIQUETAS_COLORES = [
    { id: 'red', nombre: 'Urgente', color: 'danger' },
    { id: 'orange', nombre: 'Importante', color: 'warning' },
    { id: 'yellow', nombre: 'Pendiente', color: 'default' },
    { id: 'green', nombre: 'Completado', color: 'success' },
    { id: 'blue', nombre: 'En Progreso', color: 'primary' },
    { id: 'purple', nombre: 'Idea', color: 'secondary' }
];

const TaskCardModal = ({ tarjeta, isOpen, onOpenChange, mode = "edit", onCreate }) => {
    const { editarTarjeta, borrarTarjeta } = useTarjetas(tarjeta.tableroId);
    const { agregarEvento, editarEvento, toggleTodo, borrarTodo } = useTodos();

    const [editData, setEditData] = useState({
        titulo: tarjeta.titulo || "",
        descripcion: tarjeta.descripcion || "",
        fechaVencimiento: tarjeta.fechaVencimiento || "",
        etiquetas: tarjeta.etiquetas || [],
        eventId: tarjeta.eventId || null
    });

    const [addToAgenda, setAddToAgenda] = useState(!!tarjeta.eventId);

    // Resetear formulario al abrir en modo create
    useEffect(() => {
        if (isOpen && mode === "create") {
            setEditData({
                titulo: "",
                descripcion: "",
                fechaVencimiento: "",
                etiquetas: [],
                eventId: null
            });
            setAddToAgenda(false);
        } else if (isOpen && mode === "edit") {
            setEditData({
                titulo: tarjeta.titulo || "",
                descripcion: tarjeta.descripcion || "",
                fechaVencimiento: tarjeta.fechaVencimiento || "",
                etiquetas: tarjeta.etiquetas || [],
                eventId: tarjeta.eventId || null
            });
            setAddToAgenda(!!tarjeta.eventId);
        }
    }, [isOpen, mode, tarjeta]);

    const handleSave = async () => {
        try {
            let currentEventId = editData.eventId;

            // Lógica de Agenda
            if (editData.fechaVencimiento) {
                if (addToAgenda) {
                    const eventoDatos = {
                        texto: editData.titulo,
                        tipo: "Tarea",
                        fechaEntrega: editData.fechaVencimiento,
                        completado: tarjeta.completada || false
                    };

                    if (currentEventId) {
                        // Actualizar evento existente
                        await editarEvento(currentEventId, eventoDatos);
                    } else {
                        // Crear nuevo evento
                        currentEventId = await agregarEvento(eventoDatos);
                    }
                } else if (!addToAgenda && currentEventId) {
                    // Si se desmarcó y existía, borrar evento
                    await borrarTodo(currentEventId);
                    currentEventId = null;
                }
            }

            // Actualizar datos con el nuevo eventId (o null)
            const finalData = { ...editData, eventId: currentEventId };

            if (mode === "create") {
                if (onCreate) {
                    await onCreate(finalData);
                }
            } else {
                await editarTarjeta(tarjeta.id, finalData);
                toast.success("Tarjeta actualizada");
            }
            onOpenChange(false);
        } catch (error) {
            console.error(mode === "create" ? "Error al crear tarjeta:" : "Error al editar tarjeta:", error);
            toast.error(mode === "create" ? "Error al crear la tarjeta" : "Error al actualizar la tarjeta");
        }
    };

    const handleDelete = async () => {
        if (!confirm("¿Eliminar esta tarjeta?")) return;

        try {
            await borrarTarjeta(tarjeta.id); // borrarTarjeta ya maneja el borrado de agenda
            toast.success("Tarjeta eliminada");
            onOpenChange(false);
        } catch (error) {
            console.error("Error al borrar tarjeta:", error);
            toast.error("Error al eliminar la tarjeta");
        }
    };

    const toggleEtiqueta = (etiqueta) => {
        const existe = editData.etiquetas.find(e => e.id === etiqueta.id);
        if (existe) {
            setEditData({
                ...editData,
                etiquetas: editData.etiquetas.filter(e => e.id !== etiqueta.id)
            });
        } else {
            setEditData({
                ...editData,
                etiquetas: [...editData.etiquetas, etiqueta]
            });
        }
    };

    return (
        <Modal
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            size="2xl"
            scrollBehavior="inside"
            placement="center"
            backdrop="blur"
            classNames={{
                base: "max-h-[90vh]"
            }}
        >
            <ModalContent>
                {(onClose) => (
                    <>
                        <ModalHeader className="flex flex-col gap-1">
                            <Input
                                value={editData.titulo}
                                onChange={(e) => setEditData({ ...editData, titulo: e.target.value })}
                                variant="bordered"
                                size="lg"
                                classNames={{
                                    input: "text-xl font-bold"
                                }}
                            />
                        </ModalHeader>

                        <ModalBody>
                            <div className="space-y-6">
                                {/* Descripción */}
                                <div>
                                    <label className="text-sm font-semibold mb-2 block">Descripción</label>
                                    <Textarea
                                        value={editData.descripcion}
                                        onChange={(e) => setEditData({ ...editData, descripcion: e.target.value })}
                                        placeholder="Agrega una descripción más detallada..."
                                        variant="bordered"
                                        minRows={4}
                                    />
                                </div>

                                {/* Fecha de Vencimiento */}
                                <div>
                                    <label className="text-sm font-semibold mb-2 block flex items-center gap-2">
                                        <Calendar size={16} />
                                        Fecha de Vencimiento
                                    </label>
                                    <div className="flex gap-4 items-center">
                                        <Input
                                            type="date"
                                            value={editData.fechaVencimiento}
                                            onChange={(e) => setEditData({ ...editData, fechaVencimiento: e.target.value })}
                                            variant="bordered"
                                            className="max-w-xs"
                                        />

                                        {editData.fechaVencimiento && (
                                            <div
                                                className={`
                                                    cursor-pointer flex items-center gap-2 px-3 py-2 rounded-lg border transition-all select-none
                                                    ${addToAgenda
                                                        ? 'bg-primary/10 border-primary text-primary'
                                                        : 'bg-default-100 border-default-200 text-default-500 hover:bg-default-200'
                                                    }
                                                `}
                                                onClick={() => setAddToAgenda(!addToAgenda)}
                                            >
                                                <CalendarPlus size={18} />
                                                <span className="text-sm font-medium">
                                                    {addToAgenda ? "Sincronizado con Agenda" : "Añadir a Agenda"}
                                                </span>
                                            </div>
                                        )}
                                    </div>
                                    {editData.fechaVencimiento && (
                                        <p className="text-xs text-default-500 mt-1">
                                            {format(new Date(editData.fechaVencimiento), "EEEE, d 'de' MMMM 'de' yyyy", { locale: es })}
                                        </p>
                                    )}
                                </div>

                                <Divider />

                                {/* Etiquetas */}
                                <div>
                                    <label className="text-sm font-semibold mb-3 block flex items-center gap-2">
                                        <Tag size={16} />
                                        Etiquetas
                                    </label>
                                    <div className="flex flex-wrap gap-2">
                                        {ETIQUETAS_COLORES.map((etiqueta) => {
                                            const isSelected = editData.etiquetas.find(e => e.id === etiqueta.id);
                                            return (
                                                <Chip
                                                    key={etiqueta.id}
                                                    color={etiqueta.color}
                                                    variant={isSelected ? "solid" : "bordered"}
                                                    onClick={() => toggleEtiqueta(etiqueta)}
                                                    className="cursor-pointer"
                                                >
                                                    {etiqueta.nombre}
                                                </Chip>
                                            );
                                        })}
                                    </div>
                                </div>

                                <Divider />

                                {/* Información */}
                                <div className="bg-default-100 rounded-lg p-3 text-xs text-default-500">
                                    <p>Creada: {tarjeta.createdAt ? format(new Date(tarjeta.createdAt.seconds * 1000), "d MMM yyyy, HH:mm", { locale: es }) : "Fecha no disponible"}</p>
                                    {tarjeta.updatedAt && (
                                        <p className="mt-1">Última modificación: {format(new Date(tarjeta.updatedAt.seconds * 1000), "d MMM yyyy, HH:mm", { locale: es })}</p>
                                    )}
                                </div>
                            </div>
                        </ModalBody>

                        <ModalFooter className="flex justify-between">
                            {mode !== "create" && (
                                <Button
                                    color="danger"
                                    variant="light"
                                    startContent={<Trash2 size={16} />}
                                    onPress={handleDelete}
                                >
                                    Eliminar
                                </Button>
                            )}
                            <div className={`flex gap-2 ${mode === "create" ? "w-full justify-end" : ""}`}>
                                <Button variant="light" onPress={onClose}>
                                    Cancelar
                                </Button>
                                <Button
                                    color="primary"
                                    startContent={<Save size={16} />}
                                    onPress={handleSave}
                                >
                                    Guardar
                                </Button>
                            </div>
                        </ModalFooter>
                    </>
                )}
            </ModalContent>
        </Modal>
    );
};

export default TaskCardModal;

